LEVEL = 1
CFG = {1: {"age_d": 30, "alg": "AES-GCM"}, 2: {"age_d": 400, "alg": "AES-GCM"}, 3: {"age_d": 30, "alg": "3DES"}}
k = CFG[LEVEL]
issues = []
if k["age_d"] > 365: issues.append("too old")
if k["alg"] not in ("AES-GCM", "ChaCha20"): issues.append("weak algorithm")
print("key:", k, "| health:", "OK" if not issues else "ALERT: " + ", ".join(issues))

